VALUES (37810, 'tt1424327', NULL, 'Eyes Wide Open', 'עיניים פקוחות', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/15AKmO30arWmZ4WuTaPdVugWZbr.jpg', 'https://image.tmdb.org/t/p/original/hDbQF1h1ncMlbu5UUW8qAA8o3gN.jpg', 'A middle-aged Orthodox Jew, Aaron, living and working in Jerusalem with his wife and children, meets a homeless 19-year-old student. Aaron offers to give Ezri work as his assistant at his family''s butcher shop. The two men grow close and their attraction becomes sexual. Aaron must now confront his own sexuality, his feelings for Ezri, and his obligations to his family and faith.', NULL, NULL, 1.1127, 6.482, 0, 1.03, '2026-11-26 02:07:22', '2026-11-26 02:07:22')
