VALUES (84306, 'tt1872818', NULL, 'Liberal Arts', 'Liberal Arts', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/yjZIATIFTiDs8rmwoF9izbBVsjg.jpg', 'https://image.tmdb.org/t/p/original/6NsUCdgCuTD3aFVZZIX8w5eD6bT.jpg', 'Newly single, 35, and uninspired by his job, Jesse Fisher worries that his best days are behind him. But no matter how much he buries his head in a book, life keeps pulling Jesse back. When his favorite college professor invites him to campus to speak at his retirement dinner, Jesse jumps at the chance.', NULL, NULL, 2.2598, 6.5, 0, 1.06, '2026-11-26 02:07:22', '2026-11-26 02:07:22')
