VALUES (47320, 'tt1315350', NULL, 'Cherry', 'Cherry', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/sTlOUvhrsiGdtwVKbdlB5pAdE2U.jpg', 'https://image.tmdb.org/t/p/original/csdiZhmXyurNpuZcZGkZr4i1UkI.jpg', 'Ivy League Freshman, Aaron Milton (17) gets a different kind of education when he falls for Linda (34) a vivacious former wild-child who has returned to college to straighten out her life. The curriculum gets more challenging when Aaron meets Linda''s sarcastic 14 year-old daughter, Beth - who quickly develops a crush on him. The math doesn''t work in either direction but the dysfunctional triangle becomes a learning experience for all involved.', NULL, NULL, 1.0099, 6.3, 0, 1.02, '2026-11-26 02:07:22', '2026-11-26 02:07:22')
