VALUES (8327, 'tt0071615', NULL, 'The Holy Mountain', 'La montaña sagrada', 'movie', 1973, 'https://image.tmdb.org/t/p/w500/oaOyrFD4ZyZZwjO8wc4b12XHcgZ.jpg', 'https://image.tmdb.org/t/p/original/oUceCsSe255ZKXCMsHhqXM1xuUp.jpg', 'The Alchemist assembles together a group of people from all walks of life to represent the planets in the solar system. The occult adept''s intention is to put his recruits through strange mystical rites and divest them of their worldly baggage before embarking on a trip to Lotus Island. There they ascend the Holy Mountain to displace the immortal gods who secretly rule the universe.', NULL, NULL, 4.3949, 7.5, 0, 1.31475748031496067e+02, '2026-07-15 12:01:52', '2026-11-26 02:07:22')
