VALUES (718558, 'tt9102084', NULL, 'Fried Barry', 'Fried Barry', 'movie', 2020, 'https://image.tmdb.org/t/p/w500/iQ2TCB6nszgFHnF1QeHJujvBIzn.jpg', 'https://image.tmdb.org/t/p/original/hYfm6bESA5cahGIOOD4gH0L4pQf.jpg', 'Barry is a drug-addled, abusive bastard who - after yet another bender - is abducted by aliens. Barry takes a backseat as an alien visitor assumes control of his body and takes it for a joyride through Cape Town. What follows is an onslaught of drugs, sex, and violence as our alien tourist enters the weird and wonderful world of humankind.', NULL, NULL, 0.865, 5.1, 0, 8.812, '2026-07-15 12:01:52', '2026-11-26 02:07:22')
