VALUES (152747, 'tt2017038', NULL, 'All Is Lost', 'All Is Lost', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/9cVA4oX2xHgiglv6hemxwAaofsq.jpg', 'https://image.tmdb.org/t/p/original/tGy0zyeljUFV20qjVmAigwnlWKv.jpg', 'During a solo voyage in the Indian Ocean, a veteran mariner awakes to find his vessel taking on water after a collision with a stray shipping container. With his radio and navigation equipment disabled, he sails unknowingly into a violent storm and barely escapes with his life. With any luck, the ocean currents may carry him into a shipping lane -- but, with supplies dwindling and the sharks circling, the sailor is forced to face his own mortality.', NULL, NULL, 2.8749, 6.644, 0, 1.78172727272727264e+01, '2026-07-20 01:02:04', '2026-11-26 02:07:22')
