VALUES (30020, 'tt0120265', NULL, 'Taste of Cherry', 'طعم گيلاس', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/vgPwjgbSdbYWrS1ty8TIZtmi6Tn.jpg', 'https://image.tmdb.org/t/p/original/44SNTCSZTdbF5bzgUy4IfPV3DUq.jpg', 'A middle-aged Tehranian man, Mr. Badii is intent on killing himself and seeks someone to bury him after his demise. Driving around the city, the seemingly well-to-do Badii meets with numerous people, including a Muslim student, asking them to take on the job, but initially he has little luck. Eventually, Badii finds a man who is up for the task because he needs the money, but his new associate soon tries to talk him out of committing suicide.', NULL, NULL, 3.5644, 7.719, 0, 22.445, '2026-07-30 18:28:39', '2026-11-26 02:07:22')
