VALUES (44018, 'tt0089960', NULL, 'Vagabond', 'Sans toit ni loi', 'movie', 1985, 'https://image.tmdb.org/t/p/w500/2KFfwiPct1hwqi9dkKqoom0BenC.jpg', 'https://image.tmdb.org/t/p/original/tKsFh8qpYyi2AMg5O8QTVdChm4k.jpg', 'Mona Bergeron is dead, her frozen body found in a ditch in the French countryside. From this, the film flashes back to the weeks leading up to her death. Through these flashbacks, Mona gradually declines as she travels from place to place, taking odd jobs and staying with whomever will offer her a place to sleep. Mona is fiercely independent, craving freedom over comfort, but it is this desire to be free that will eventually lead to her demise.', NULL, NULL, 2.7626, 7.355, 0, 10.27, '2026-08-04 03:20:13', '2026-11-26 02:07:22')
