VALUES (125509, 'tt2375779', NULL, 'Wrong Turn 5: Bloodlines', 'Wrong Turn 5: Bloodlines', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/8fABep8FSRpeo8Ea4j3rfnoVgkg.jpg', 'https://image.tmdb.org/t/p/original/6PTWsiDugvnI44QwmP2f2Yq2fhN.jpg', 'A small West Virginia town is hosting the legendary Mountain Man Festival on Halloween, where throngs of costumed party goers gather for a wild night of music and mischief. But an inbred family of hillbilly cannibals kill the fun when they trick and treat themselves to a group of visiting college students.', NULL, NULL, 7.4641, 5.469, 0, 6.58, '2026-08-19 01:49:52', '2026-11-26 02:07:22')
